void delay(uint32_t x)
{
    for(uint32_t i = 0; i < x; i++)
        for(uint32_t j = 0; j < 800; j++);
}

void load()
{
	GPIOB_ODR |=  (1 << LOAD_BIT);
	delay(2);
	GPIOB_ODR &= ~(1 << LOAD_BIT);

}
void gpioInit()
{
	RCC_AHBENR  |=  (1 << 18);
	GPIOB_MODER &= ~((3 << DATA_BIT*2) | (3 << CLK_BIT*2) | (3 << LOAD_BIT*2));
	GPIOB_MODER |=  ((1 << DATA_BIT*2) | (1 << CLK_BIT*2) | (1 << LOAD_BIT*2));
	GPIOB_ODR 	&= ~((1 << DATA_BIT)   | (1 << CLK_BIT)   | (1 << LOAD_BIT));
}

void serialMax7219(uint8_t data)
{
	  for(int8_t i = 0; i < 8; i++)
	    {
	    	GPIOB_ODR &= ~(1 << CLK_BIT);
	        if(data & (1 << 7))
	            GPIOB_ODR |=  (1 << DATA_BIT);
	        else
	            GPIOB_ODR &= ~(1 << DATA_BIT);
//	        delay(1);
	        GPIOB_ODR |=  (1 << CLK_BIT);
	        data = data << 1;
//	        delay(1);
	    }
}

void writeToMax7219(uint8_t address, uint8_t data)
{
    GPIOB_ODR &= ~(1 << LOAD_BIT);
    serialMax7219(address);
    serialMax7219(data);
}



void max7219_init()
{
	delay(20);
	writeToMax7219(decodeModeAddress,        			   noDecodeData);
	load();
	delay(20);

	writeToMax7219(intensityRegisterAddress, 					   0x01);
	load();
	delay(20);

	writeToMax7219(scanLimitRegisterAddress,  				  allDigits);
	load();
	delay(20);

	writeToMax7219(shutDownAddress,            		normalOperationData);
	load();
	delay(20);

	writeToMax7219(displayTestRegisterAddress, 	testNormalOperationData);
	load();
	delay(20);
}

void ClearDisplay()
{
  for(unsigned char col = 1; col < 9; col++)
  {
   	writeToMax7219(col, 0);
   	load();
  }

}


void printd(char *Str)
{
  char Temp[40];
  for(int i = 0; i < 40; i++)   Temp[i] = 0x00;

  for(int Row = 0; *Str != '\0'; Row++)
  {
	  for(int Col = 0; Col < 8; Col++)
	  {
		Temp[(Row * 8)+Col] = ASCII[*Str - 32][Col];
	  }
	  Str++;
    }

    for(int col = 1; col < 8; col++)
    {
    	 writeToMax7219(col , Temp[col - 1]       );
		 writeToMax7219(col , Temp[col + 8 - 1]   );
		 writeToMax7219(col , Temp[col + 16 - 1]  );
		 writeToMax7219(col , Temp[col + 24 - 1]  );
		 load();
    }
}


void prints(char *Str, uint32_t speed)
{
	uint16_t Temp[800];
	int stringCounter = 0;
	for(int i = 0; i < 800; i++)	Temp[i] = 0x00;

	for(int Row = 0; *Str != '\0'; Row++)
	{
	  for(int Col = 0; Col < 8; Col++)
	  {
		Temp[(Row * 8)+Col + 32] = ASCII[*Str - 32][Col];
	  }
	  Str++;
	  stringCounter++;
	}
for(int j = 0; j < (stringCounter*8)+32; j++)
{
	for(int row = 1; row < 8; row++)
	{
		 writeToMax7219(row , Temp[row - 1]       );
		 writeToMax7219(row , Temp[row + 8 - 1]  );
		 writeToMax7219(row , Temp[row + 16 - 1]  );
		 writeToMax7219(row , Temp[row + 24 - 1]  );
		 load();
	}
	delay(speed);

	for(int i  = 0; i < 8; i++)
	{
		for(int k = 0; k <= (stringCounter-1); k++)
		{
			Temp[i+(k*8)]  = Temp[i+(k*8)] << 1;
			Temp[i+(k*8)] |= (Temp[i+((k+1)*8)] >> 7);
		}
		Temp[i+(stringCounter*8)] = Temp[i+(stringCounter*8)] << 1;
	}
}
}



void adc1_init(void)
{
    /* Enable GPIOA + ADC clocks */
    RCC_AHBENR |= (1 << 17);    // GPIOAEN
    RCC_AHBENR |= (1 << 28);    // ADC12EN

    /* PA0 analog */
    GPIOA_MODER |=  (3 << (0 * 2));
    GPIOA_PUPDR &= ~(3 << (0 * 2));
    printd("ADC2");
    /* Ensure ADC disabled */
    if (ADC1_CR & 1)
    {
    	printd("ADC3");
        ADC1_CR |= (1 << 1);           // ADDIS
        while (ADC1_CR & 1);
        printd("ADC4");
    }

    /* ADC clock = HCLK */
    ADC_CCR &= ~(3 << 16);
    ADC_CCR |=  (1 << 16);             // CKMODE = HCLK/1

    /* Exit deep power-down */
    ADC1_CR &= ~(1 << 29);

    /* Enable regulator */
    ADC1_CR |= (1 << 28);

    /* Regulator stabilization delay (>10 µs @ 8 MHz) */
    for (volatile uint32_t i = 0; i < 200000; i++)
        __asm volatile ("nop");
    printd("ADC5");
    /* Start calibration */
    ADC1_CR |= (1 << 31);
    while (ADC1_CR & (1 << 31));
    printd("ADC6");
    /* ADC configuration */
    ADC1_CFGR = 0x00000000;
    ADC1_SMPR1 |= (4 << 3);     // Channel 1 sample time
    ADC1_SQR1  = (1 << 6);      // 1 conversion, CH1
    printd("ADC7");
    /* Enable ADC */
    ADC1_CR |= 1;
    while (!(ADC1_ISR & 1));
    ADC1_ISR |= 1;
    printd("ADC8");
}

uint16_t adc1_read(void)
{
    ADC1_CR |= (1 << 2);                  // ADSTART
    while (!(ADC1_ISR & (1 << 2)));       // EOC
    return (uint16_t)ADC1_DR;
}


void u16_to_str(uint16_t val, char *buf)
{
    buf[3] = (val % 10) + '0'; val /= 10;
    buf[2] = (val % 10) + '0'; val /= 10;
    buf[1] = (val % 10) + '0'; val /= 10;
    buf[0] = (val % 10) + '0';
    buf[4] = ' ';
    buf[5] = '\0';
}



int main(void)
{
    char adc_str[6];
    uint16_t adc_val;
	char buf[40];
    gpioInit();
    delay(50);
    max7219_init();
    ClearDisplay();
    ClearDisplay();
    printd("LOAD");
    delay(2000);

    adc1_init();
    prints("Selah India Pvt Ltd     ", 30);
    delay(2000);
    ClearDisplay();


    while (1)
    {

    	adc_val = adc1_read();     		// 0–4095
        u16_to_str(adc_val, adc_str);

        printd(adc_str);           		// display ADC value
        delay(500);

    }
}
